import React, { useState, useRef, useEffect } from 'react';
import { X, Send, Bot, User, RefreshCw, Sparkles } from 'lucide-react';
import { useCart } from '../context/CartContext';
import { useUser } from '../context/UserContext';
import { products } from '../data/products';
import { GoogleGenAI } from "@google/genai";

type Sender = 'user' | 'bot';

interface Message {
  id: number;
  text: string;
  sender: Sender;
}

interface QuickReply {
  label: string;
  action: string;
}

const ChatWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { 
      id: 1, 
      text: "👋 Hi! I'm Smartify Assist.\nI can help you explore our latest tech, track orders, or find the perfect gadget.\n\nHow can I help you today?", 
      sender: 'bot' 
    }
  ]);
  const [inputValue, setInputValue] = useState("");
  const [isTyping, setIsTyping] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const { cart, totalAmount } = useCart();
  const { user, orders } = useUser();

  const toggleChat = () => setIsOpen(!isOpen);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen, isTyping]);

  // Quick Replies Configuration
  const defaultQuickReplies: QuickReply[] = [
    { label: "🔍 Suggest Products", action: "Suggest some trending products" },
    { label: "📦 Track Order", action: "Where is my order?" },
    { label: "🛒 My Cart", action: "What is in my cart?" },
    { label: "🎉 Deals", action: "Show me today's offers" },
  ];

  const handleQuickReply = (text: string) => {
    handleSendMessage(undefined, text);
  };

  // Helper to format text with basic markdown-like features (Bold and Newlines)
  const formatMessage = (text: string) => {
    return text.split('\n').map((line, i) => (
      <React.Fragment key={i}>
        {line.split(/(\*\*.*?\*\*)/).map((part, j) => 
          part.startsWith('**') && part.endsWith('**') ? (
            <strong key={j} className="font-bold text-slate-900">{part.slice(2, -2)}</strong>
          ) : (
            part
          )
        )}
        <br />
      </React.Fragment>
    ));
  };

  const generateAIResponse = async (userQuery: string, currentHistory: Message[]) => {
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // 1. Prepare Context Data
      const productCatalog = products.map(p => 
        `- ${p.name} (${p.category}): ₹${p.price} ${p.discount ? `(${p.discount}% Off)` : ''} - ${p.description}`
      ).join('\n');

      const cartContext = cart.length > 0 
        ? `User Cart: ${cart.map(i => `${i.quantity}x ${i.name}`).join(', ')}. Total: ₹${totalAmount}` 
        : "User Cart is empty.";

      const orderContext = orders.length > 0
        ? `User Orders: ${orders.map(o => `ID ${o.id} (${o.status}, ₹${o.total})`).join(', ')}`
        : "No recent orders.";

      const userContext = user ? `User Name: ${user.name}` : "Guest User";

      // 2. System Instruction
      const systemInstruction = `
        You are Smartify Assist, an advanced AI shopping assistant for a futuristic electronics store named "Smartify".

        YOUR PERSONALITY:
        - Friendly, professional, and slightly futuristic/tech-savvy.
        - Concise and helpful. Use emojis sparingly but effectively.
        - You are an expert on electronics (Mobiles, Wearables, Audio, Smart Home, Gaming).

        STORE POLICIES:
        - Shipping: 3-5 business days standard. Express available in metros.
        - Returns: 7-day return policy for undamaged items.
        - Warranty: 1-year manufacturer warranty on all devices.

        CURRENT USER CONTEXT:
        ${userContext}
        ${cartContext}
        ${orderContext}

        PRODUCT CATALOG (Use this to recommend items):
        ${productCatalog}

        INSTRUCTIONS:
        - If asked about products, recommend from the catalog with prices.
        - If asked about orders, use the Order Context.
        - If asked about the cart, summarize it.
        - Format key details (like product names or prices) in **bold**.
        - Keep responses short (under 3-4 sentences) unless listing products.
      `;

      // 3. Build History for Gemini
      // We limit history to last 10 turns to save tokens and context
      // IMPORTANT: Filter out messages that might not be in the correct role format for the API if needed.
      // Here we map 'bot' to 'model'.
      const historyParts = currentHistory.slice(-10).map(msg => ({
        role: msg.sender === 'user' ? 'user' : 'model',
        parts: [{ text: msg.text }]
      }));

      // 4. Call API
      // We pass the history + current prompt as contents.
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: [
          ...historyParts,
          { role: 'user', parts: [{ text: userQuery }] }
        ],
        config: {
          systemInstruction: systemInstruction,
          temperature: 0.7,
        }
      });

      // Correctly access the text property
      const botText = response.text || "I'm processing that information but couldn't generate a text response.";

      setMessages(prev => [...prev, { id: Date.now(), text: botText, sender: 'bot' }]);

    } catch (error) {
      console.error("AI Error:", error);
      setMessages(prev => [...prev, { 
        id: Date.now(), 
        text: "I'm having trouble connecting to the neural network right now. Please try again later.", 
        sender: 'bot' 
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  const handleSendMessage = (e?: React.FormEvent, manualText?: string) => {
    if (e) e.preventDefault();

    const textToSend = manualText || inputValue;
    if (!textToSend.trim()) return;

    // Optimistic UI update
    const newUserMsg: Message = { id: Date.now(), text: textToSend, sender: 'user' };
    const updatedMessages = [...messages, newUserMsg];

    setMessages(updatedMessages);
    setInputValue("");

    // Trigger AI
    generateAIResponse(textToSend, updatedMessages);
  };

  return (
    <>
      {/* Floating Toggle Button */}
      <button
        onClick={toggleChat}
        className={`fixed bottom-8 right-8 z-50 group flex items-center justify-center gap-3 bg-white/80 backdrop-blur-md border border-white/50 shadow-[0_8px_32px_rgba(37,99,235,0.25)] p-4 rounded-full transition-all duration-500 hover:scale-110 hover:shadow-[0_8px_32px_rgba(37,99,235,0.4)] hover:bg-white ${isOpen ? 'scale-0 opacity-0 pointer-events-none' : 'opacity-100'}`}
      >
        <div className="relative">
             <div className="absolute inset-0 bg-blue-500 rounded-full blur opacity-20 animate-pulse"></div>
             <Bot size={32} className="text-blue-600 relative z-10" />
             <span className="absolute -top-1 -right-1 flex h-3.5 w-3.5">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-blue-400 opacity-75"></span>
              <span className="relative inline-flex rounded-full h-3.5 w-3.5 bg-green-500 border-2 border-white"></span>
            </span>
        </div>
      </button>

      {/* Chat Window */}
      <div 
        className={`fixed z-50 transition-all duration-500 cubic-bezier(0.16, 1, 0.3, 1) transform ${isOpen ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 translate-y-20 scale-90 pointer-events-none'}`}
        style={{ 
          bottom: '100px', 
          right: '32px', 
          width: '380px', 
          height: '650px',
          maxHeight: 'calc(100vh - 120px)'
        }}
      >
        <div className="w-full h-full glass-panel flex flex-col overflow-hidden shadow-[0_20px_60px_-15px_rgba(0,0,0,0.15)] border-white/60 rounded-[2.5rem] bg-white/60 backdrop-blur-xl ring-1 ring-white/50">

          {/* Header */}
          <div className="bg-gradient-to-r from-blue-600 via-blue-500 to-purple-600 p-5 flex justify-between items-center text-white shadow-lg relative overflow-hidden">
            {/* Abstract Header decoration */}
            <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full blur-2xl transform translate-x-10 -translate-y-10"></div>

            <div className="flex items-center gap-3 relative z-10">
              <div className="bg-white/20 p-2.5 rounded-2xl backdrop-blur-md shadow-inner border border-white/20">
                  <Sparkles size={20} className="text-yellow-300 fill-yellow-300" />
              </div>
              <div>
                <h3 className="font-bold text-lg font-heading tracking-wide">Smartify AI</h3>
                <p className="text-[11px] text-blue-100 font-medium flex items-center gap-1.5 opacity-90">
                  <span className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse shadow-[0_0_8px_rgba(74,222,128,0.8)]"></span> 
                  Online & Ready
                </p>
              </div>
            </div>
            <div className="flex gap-1 relative z-10">
                <button 
                  onClick={() => setMessages([{ id: 1, text: "👋 Hi! I'm Smartify Assist.\nI can help you explore our latest tech, track orders, or find the perfect gadget.\n\nHow can I help you today?", sender: 'bot' }])} 
                  className="bg-white/10 hover:bg-white/20 p-2 rounded-full text-white transition-all hover:rotate-180 duration-500" 
                  title="Reset Chat"
                >
                    <RefreshCw size={16} />
                </button>
                <button 
                  onClick={toggleChat} 
                  className="bg-white/10 hover:bg-red-500/20 hover:text-red-100 p-2 rounded-full text-white transition-all"
                >
                    <X size={16} />
                </button>
            </div>
          </div>

          {/* Messages Area */}
          <div className="flex-1 overflow-y-auto p-5 space-y-6 bg-slate-50/30 custom-scrollbar scroll-smooth">
            {messages.map((msg) => (
              <div key={msg.id} className={`flex w-full ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>

