           - If asked for account help, say: "I can help you with: • Login issues • Password reset • Profile update"

        9. CUSTOMER SUPPORT:
           - If user wants to talk to a human or if you cannot handle a request, say: "I’m still learning and can’t handle that request right now. Would you like to connect with customer support?"

        --- ERROR HANDLING & FALLBACK ---
        - If input is unclear/gibberish: "❗ I didn’t understand that. Please select an option below or try again."
        - Always maintain context (budget, category, order ID).
        - End conversations politely when the user is done: "😊 Happy to help! If you need anything else, just ask. Thank you for shopping with Smartify."

        Response Rules:
        - Keep responses concise.
        - Use **bold** for product names and prices.
        - Use emojis defined in the scripts (📦, 🎉, ❗, 😊).
      `;

      // Build History
      const historyParts = currentHistory.slice(-10).map(msg => ({
        role: msg.sender === 'user' ? 'user' : 'model',
        parts: [{ text: msg.text }]
      }));

      // Call API
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: [
          ...historyParts,
          { role: 'user', parts: [{ text: userQuery }] }
        ],
        config: {
          systemInstruction: systemInstruction,
          temperature: 0.5, // Lower temperature for more adherence to scripts
        }
      });

      const botText = response.text || "❗ I didn’t understand that. Please select an option below or try again.";

      setMessages(prev => [...prev, { id: Date.now(), text: botText, sender: 'bot' }]);

    } catch (error) {
      console.error("AI Error:", error);
      // 11. Error Handling Fallback
      setMessages(prev => [...prev, { 
        id: Date.now(), 
        text: "❗ I didn’t understand that. Please select an option below or try again.", 
        sender: 'bot' 
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  const handleSendMessage = (e?: React.FormEvent, manualText?: string) => {
    if (e) e.preventDefault();

    const textToSend = manualText || inputValue;
    if (!textToSend.trim()) return;

    // Optimistic UI update
    const newUserMsg: Message = { id: Date.now(), text: textToSend, sender: 'user' };
