        <div className="w-full h-full glass-panel flex flex-col overflow-hidden shadow-[0_20px_60px_-15px_rgba(0,0,0,0.15)] border-white/60 rounded-[2.5rem] bg-white/60 backdrop-blur-xl ring-1 ring-white/50">

