import React, { useState, useRef, useEffect } from 'react';
import { X, Send, Bot, User, RefreshCw, Sparkles, MessageSquare } from 'lucide-react';
import { useCart } from '../context/CartContext';
import { useUser } from '../context/UserContext';
import { products } from '../data/products';
import { GoogleGenAI } from "@google/genai";

type Sender = 'user' | 'bot';

interface Message {
  id: number;
  text: string;
  sender: Sender;
}

interface QuickReply {
  label: string;
  action: string;
}

const ChatWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);

  // 1. Welcome Message & Introduction
  const [messages, setMessages] = useState<Message[]>([
    { 
      id: 1, 
      text: "👋 Hi! Welcome to Smartify.\nI’m Smartify Assist, your AI shopping assistant.\nI can help you find products, track orders, check offers, and answer your questions.\nHow can I help you today?", 
      sender: 'bot' 
    }
  ]);

  const [inputValue, setInputValue] = useState("");
  const [isTyping, setIsTyping] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const { cart, totalAmount } = useCart();
  const { user, orders } = useUser();

  const toggleChat = () => setIsOpen(!isOpen);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen, isTyping]);

  // 2. Show Quick Reply Options
  const defaultQuickReplies: QuickReply[] = [
    { label: "🔍 Browse Products", action: "I want to browse products" },
    { label: "🛒 View Cart", action: "What is in my cart?" },
    { label: "📦 Track Order", action: "Track my order" },
    { label: "🎉 Offers & Deals", action: "Show me offers" },
    { label: "👤 Account Help", action: "I need account help" },
    { label: "📞 Customer Support", action: "Talk to support" },
  ];

  const handleQuickReply = (text: string) => {
    handleSendMessage(undefined, text);
  };

  // Helper to format text with basic markdown-like features (Bold and Newlines)
  const formatMessage = (text: string) => {
    return text.split('\n').map((line, i) => (
      <React.Fragment key={i}>
        {line.split(/(\*\*.*?\*\*)/).map((part, j) => 
          part.startsWith('**') && part.endsWith('**') ? (
            <strong key={j} className="font-bold text-slate-900">{part.slice(2, -2)}</strong>
          ) : (
            part
          )
        )}
        <br />
      </React.Fragment>
    ));
  };

  const generateAIResponse = async (userQuery: string, currentHistory: Message[]) => {
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Prepare Context Data
      const productCatalog = products.map(p => 
        `- ${p.name} (${p.category}): ₹${p.price} ${p.discount ? `(${p.discount}% Off)` : ''} - ${p.description}`
      ).join('\n');

      const cartContext = cart.length > 0 
        ? `User Cart: ${cart.map(i => `${i.quantity}x ${i.name}`).join(', ')}. Total: ₹${totalAmount}` 
        : "User Cart is empty.";

      const orderContext = orders.length > 0
        ? `User Orders: ${orders.map(o => `ID ${o.id} (${o.status}, ₹${o.total})`).join(', ')}`
        : "No recent orders.";

      const userContext = user ? `User Name: ${user.name}` : "Guest User";

      // System Instruction - Implementing the 14-Point Guideline
      const systemInstruction = `
        You are Smartify Assist, an AI shopping assistant for the electronics store "Smartify".
        Your tone is helpful, friendly, professional, and easy to understand.

        --- STORE KNOWLEDGE BASE ---
        1. Delivery: Standard delivery takes 3–5 business days. Express options available.
        2. Returns: Returns allowed within 7 days of delivery. Refunds in 5–7 working days.
        3. Warranty: All Smartify wearables/products come with a 1-year warranty.
        4. Payment: We support UPI, Cards, Net Banking, and COD.
        5. Categories: Smartphones, Wearables, Audio Devices, Gaming, Smart Home, Accessories.

        --- CURRENT CONTEXT ---
        ${userContext}
        ${cartContext}
        ${orderContext}

        --- PRODUCT CATALOG ---
        ${productCatalog}

        --- CONVERSATION FLOW SCRIPTS (FOLLOW STRICTLY) ---

        1. PRODUCT BROWSING:
           - If user wants to browse or search products, ask: "Which category are you interested in?" (List categories if needed).
           - Once category is known, ask: "Do you have a budget range?"

        2. PRODUCT RECOMMENDATION:
           - When suggesting products based on preference, say: "Based on your preference, here are some recommended products. Would you like to view details or add to cart?"
           - List 2-3 specific products from the catalog with prices in **bold**.

        3. ORDER TRACKING:
           - If user asks to track order:
             - If Order ID is NOT in the prompt or context, say: "Please enter your Order ID."
             - If Order ID is provided (or found in context ${orderContext}), say: "📦 Your order is currently out for delivery and will arrive soon."

        4. OFFERS & DEALS:
           - If user asks for offers, say: 
             "🎉 Current offers available:
             • Flat discounts on wearables
             • Special deals on gaming accessories
