          <div className="flex-1 overflow-y-auto p-5 space-y-6 bg-slate-50/30 custom-scrollbar scroll-smooth">
            {messages.map((msg) => (
              <div key={msg.id} className={`flex w-full ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>

                {msg.sender === 'bot' && (
                    <div className="w-8 h-8 rounded-2xl bg-gradient-to-br from-blue-100 to-purple-100 border border-white flex items-center justify-center text-blue-600 text-xs mr-3 shrink-0 mt-1 shadow-sm">
                        <Bot size={16} />
                    </div>
                )}

                <div 
                  className={`max-w-[85%] p-4 text-sm leading-relaxed shadow-sm backdrop-blur-sm transition-all duration-300 animate-fade-in-up ${
                    msg.sender === 'user' 
                      ? 'bg-gradient-to-br from-blue-600 to-blue-700 text-white rounded-2xl rounded-tr-none shadow-blue-500/20' 
                      : 'bg-white/80 border border-white/60 text-slate-700 rounded-2xl rounded-tl-none shadow-slate-200/50'
                  }`}
                >
                  {formatMessage(msg.text)}
                </div>

                {msg.sender === 'user' && (
                    <div className="w-8 h-8 rounded-2xl bg-slate-200 border border-white flex items-center justify-center text-slate-500 text-xs ml-3 shrink-0 mt-1">
                        <User size={16} />
                    </div>
                )}
              </div>
            ))}

            {isTyping && (
                <div className="flex justify-start animate-fade-in-up">
                    <div className="w-8 h-8 rounded-2xl bg-gradient-to-br from-blue-100 to-purple-100 border border-white flex items-center justify-center text-blue-600 text-xs mr-3 shrink-0 mt-1 shadow-sm">
                        <Bot size={16} />
                    </div>
                    <div className="bg-white/80 border border-white/60 px-4 py-3 rounded-2xl rounded-tl-none shadow-sm flex gap-1.5 items-center h-10">
                        <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce"></span>
                        <span className="w-1.5 h-1.5 bg-purple-400 rounded-full animate-bounce" style={{animationDelay: '0.15s'}}></span>
                        <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce" style={{animationDelay: '0.3s'}}></span>
                    </div>
                </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Quick Replies */}
          <div className="px-5 pb-3 bg-gradient-to-t from-white via-white/80 to-transparent pt-4">
             <div className="flex gap-2 overflow-x-auto custom-scrollbar pb-2 mask-linear">
               {defaultQuickReplies.map((qr) => (
                   <button 
                      key={qr.label}
                      onClick={() => handleQuickReply(qr.action)}
                      className="whitespace-nowrap px-4 py-2 bg-white/80 backdrop-blur-sm border border-blue-100 text-blue-600 rounded-xl text-xs font-bold hover:bg-blue-600 hover:text-white hover:border-blue-600 hover:shadow-lg hover:shadow-blue-500/20 transition-all duration-300 flex-shrink-0"
                   >
                      {qr.label}
                   </button>
               ))}
             </div>
          </div>

          {/* Input Area */}
          <form onSubmit={handleSendMessage} className="p-4 bg-white border-t border-slate-100 flex gap-3 relative z-20">
            <input 
              type="text" 
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              placeholder="Ask Smartify Assist..."
              className="flex-1 bg-slate-50 border-slate-200 focus:bg-white focus:border-blue-400 rounded-2xl px-5 py-3.5 text-sm transition-all outline-none border focus:shadow-[0_0_0_4px_rgba(59,130,246,0.1)] placeholder:text-slate-400"
            />
            <button 
              type="submit" 
              className="bg-slate-900 hover:bg-blue-600 text-white w-12 h-12 rounded-2xl transition-all duration-300 flex items-center justify-center shadow-lg shadow-slate-200 hover:shadow-blue-500/30 hover:scale-105 active:scale-95 disabled:opacity-50 disabled:scale-100 disabled:hover:bg-slate-900"
              disabled={!inputValue.trim() || isTyping}
            >
              <Send size={20} className={inputValue.trim() ? "translate-x-0.5 translate-y-[-1px]" : ""} />
            </button>
          </form>
        </div>
      </div>
    </>
  );
};

export default ChatWidget;

import React, { useRef, Suspense, ReactNode } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Stage, Float, useTexture } from '@react-three/drei';
import * as THREE from 'three';

// Define R3F elements as constants with 'any' type to bypass 
// missing JSX.IntrinsicElements definition in the current environment.
const Mesh = 'mesh' as any;
const BoxGeometry = 'boxGeometry' as any;
const MeshStandardMaterial = 'meshStandardMaterial' as any;

interface ErrorBoundaryProps {
  fallback: ReactNode;
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

// Simple Error Boundary Component to catch texture loading errors
class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(error: any) {
    return { hasError: true };
  }

  componentDidCatch(error: any, errorInfo: any) {
    console.error("3D Viewer Error:", error);
  }

  render() {
    if (this.state.hasError) {
      return this.props.fallback;
    }
    return this.props.children;
  }
}

function Model({ imageUrl }: { imageUrl: string }) {
  const meshRef = useRef<THREE.Mesh>(null);
  // useTexture will suspend if loading, or throw if failed
  const texture = useTexture(imageUrl);

  useFrame((state) => {
    if (meshRef.current) {
      // Gentle rotation
      meshRef.current.rotation.y = state.clock.getElapsedTime() * 0.3;
    }
  });

  return (
    <Float speed={2} rotationIntensity={0.5} floatIntensity={1}>
      <Mesh ref={meshRef}>
        {/* Render a rounded box as the product representation */}
        <BoxGeometry args={[2.5, 2.5, 2.5]} />
        <MeshStandardMaterial map={texture} roughness={0.3} metalness={0.1} />
      </Mesh>
    </Float>
  );
}

function FallbackModel() {
   const meshRef = useRef<THREE.Mesh>(null);
   useFrame((state) => {
    if (meshRef.current) {
      meshRef.current.rotation.y = state.clock.getElapsedTime() * 0.3;
      meshRef.current.rotation.x = state.clock.getElapsedTime() * 0.2;
    }
  });

  return (
    <Float speed={2} rotationIntensity={0.5} floatIntensity={1}>
      <Mesh ref={meshRef}>
        <BoxGeometry args={[2.5, 2.5, 2.5]} />
        <MeshStandardMaterial color="#AEE6F9" roughness={0.3} metalness={0.1} />
      </Mesh>
    </Float>
  );
}

function Loader() {
  return (
    <Mesh>
      <BoxGeometry args={[1, 1, 1]} />
      <MeshStandardMaterial color="#cbd5e1" wireframe />
    </Mesh>
  );
}

const Product3DViewer: React.FC<{ imageUrl: string }> = ({ imageUrl }) => {
  return (
    <div className="w-full h-full cursor-move bg-transparent">
      <Canvas shadows dpr={[1, 2]} camera={{ fov: 50, position: [0, 0, 5] }}>
        <Suspense fallback={<Loader />}>
          <ErrorBoundary fallback={<FallbackModel />}>
             <Stage environment="city" intensity={0.5} shadows={{ type: 'contact', opacity: 0.4, blur: 2 }}>
               <Model imageUrl={imageUrl} />
             </Stage>
          </ErrorBoundary>
        </Suspense>
        <OrbitControls autoRotate autoRotateSpeed={2} enableZoom={false} />
      </Canvas>
    </div>
  );
};

export default Product3DViewer;
